<?php
namespace App\Http\Controllers;
use App\Services\{LeadDiscoveryService,WorkspaceContext as W,CrmService};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{Crypt,DB};
class DiscoveryController extends Controller {
 public function index(){W::authorize('discovery.view');$searches=DB::table('discovery_searches')->where('tenant_id',W::id())->latest()->get();$candidates=DB::table('discovery_candidates')->where('tenant_id',W::id())->latest()->paginate(25);$runs=DB::table('discovery_runs')->where('tenant_id',W::id())->latest()->limit(12)->get();$keyHint=DB::table('tenant_integrations')->where('tenant_id',W::id())->where('provider','apollo')->value('key_hint');return view('crm.discovery',compact('searches','candidates','runs','keyHint'));}
 public function credentials(Request $r){W::authorize('integrations.manage');$d=$r->validate(['api_key'=>'required|string|min:12|max:400']);DB::table('tenant_integrations')->updateOrInsert(['tenant_id'=>W::id(),'provider'=>'apollo'],['encrypted_key'=>Crypt::encryptString($d['api_key']),'key_hint'=>substr($d['api_key'],-4),'updated_at'=>now()]);return back()->with('success','Apollo API credential saved encrypted.');}
 public function addSearch(Request $r){W::authorize('discovery.search');$d=$r->validate(['name'=>'required|string|max:120','query'=>'nullable|string|max:150','industry'=>'nullable|string|max:100','location'=>'nullable|string|max:120','headcount'=>'nullable|regex:/^\d{1,7},\d{1,7}$/','frequency'=>'required|in:manual,daily,weekly']);abort_unless(!empty($d['query'])||!empty($d['industry'])||!empty($d['location']),422,'Specify a meaningful search filter.');DB::table('discovery_searches')->insert($d+['tenant_id'=>W::id(),'active'=>true,'created_by'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Search saved. Run it now or let the scheduler handle recurring searches.');}
 public function toggleSearch(Request $r,int $id){W::authorize('discovery.search');$d=$r->validate(['active'=>'required|boolean']);abort_unless(DB::table('discovery_searches')->where('tenant_id',W::id())->where('id',$id)->update(['active'=>$d['active'],'updated_at'=>now()]),404);return back()->with('success','Discovery schedule updated.');}
 public function run(int $id,LeadDiscoveryService $discovery){W::authorize('discovery.search');try{$count=$discovery->search(W::id(),$id,auth()->id());return back()->with('success',"Search completed. {$count} new business candidates were added for review.");}catch(\Throwable $e){report($e);return back()->withErrors(['discovery'=>'Search failed: '.(str_contains($e->getMessage(),'Apollo search returned')?$e->getMessage():'Check integration settings and the latest run status.')]);}}
 public function review(Request $r,int $id){W::authorize('discovery.import');$d=$r->validate(['decision'=>'required|in:approve,dismiss']);$tenant=W::id();$candidate=DB::table('discovery_candidates')->where('tenant_id',$tenant)->where('id',$id)->first();abort_unless($candidate,404);abort_unless($candidate->status==='pending',422,'Already reviewed.');
  DB::transaction(function()use($candidate,$d,$tenant,$id){$locked=DB::table('discovery_candidates')->where('tenant_id',$tenant)->where('id',$id)->lockForUpdate()->first();abort_unless($locked && $locked->status==='pending',422,'Already reviewed.');if($d['decision']==='dismiss'){DB::table('discovery_candidates')->where('id',$id)->where('tenant_id',$tenant)->update(['status'=>'dismissed','reviewed_at'=>now()]);return;}
   $crm=app(CrmService::class);$existing=$locked->domain?$crm->query('companies',$tenant)->where('domain',$locked->domain)->first():null;
   if(!$existing)$existing=$crm->query('companies',$tenant)->where('name',$locked->name)->first();
   $company=$existing?:$crm->save('companies',$tenant,array_filter(['name'=>$locked->name,'domain'=>$locked->domain,'industry'=>$locked->industry,'city'=>$locked->city,'country'=>$locked->country,'employees'=>$locked->employees],fn($v)=>$v!==null && $v!==''),null,auth()->id());
   $leads=$crm->query('leads',$tenant)->where('company_id',$company->id)->whereIn('status',['new','working','qualified'])->exists();
   if(!$leads)$crm->save('leads',$tenant,['name'=>$locked->name.' — business prospect','company_name'=>$locked->name,'company_id'=>$company->id,'status'=>'new','source'=>'Apollo organization search','score'=>$locked->fit_score,'owner_id'=>auth()->id()],null,auth()->id());
   DB::table('discovery_candidates')->where('id',$id)->where('tenant_id',$tenant)->update(['status'=>'approved','company_id'=>$company->id,'reviewed_at'=>now()]);
  });return back()->with('success',$d['decision']==='approve'?'Business approved and linked to CRM.':'Candidate dismissed.');
 }
}
